    prerequisites: ['lr-principle-application', 'f-conditional', 'f-premise-conclusion'],
    estimatedSeconds: 85,
    sourceType: 'original',
    hints: [
'The principle says liability requires the defect to predate the sale. Which scenarios actually establish that, rather than assuming it?',
'Watch for liability imposed after misuse, or denied for reasons like sale price that the principle never mentions.',
'The correct scenario shows the defect existed at manufacture and holds the manufacturer liable on that basis.',
    ],
    labels: { topic: 'manufacturer liability' },
